from sympy import *
from sympy.functions.elementary.piecewise import Piecewise

n = Symbol('n', integer=True, positive=True)
j = Symbol('j', integer=True)

pw = Piecewise((1, And(0 <= j, j <= n-1)), (0, True))

def match_boxcar_piecewise_sum(f, i, a, b):
    from sympy.logic.boolalg import And
    from sympy.core.relational import Relational
    from sympy.core.singleton import S
    if not isinstance(f, Piecewise):
        return None
    box_expr = None
    box_ok = False
    zero_elsewhere = True
    for expr, cond in f.args:
        if cond == True:
            if expr != S.Zero:
                zero_elsewhere = False
            continue
        if i not in cond.free_symbols:
            continue
        rels = cond.args if isinstance(cond, And) else (cond,)
        if len(rels) != 2:
            continue
        low_ok = False
        high_ok = False
        for r in rels:
            if not isinstance(r, Relational):
                break
            lhs, rhs = r.lhs, r.rhs
            if r.rel_op == "<=":
                if lhs == a and rhs == i:
                    low_ok = True
                if lhs == i and rhs == b:
                    high_ok = True
            elif r.rel_op == ">=":
                if lhs == i and rhs == a:
                    low_ok = True
                if lhs == b and rhs == i:
                    high_ok = True
        else:
            if low_ok and high_ok and i not in expr.free_symbols:
                box_expr = expr
                box_ok = True
        if not (low_ok and high_ok):
            continue
    if box_ok and zero_elsewhere and box_expr is not None:
        return simplify(box_expr * (b - a + 1))
    return None

res = match_boxcar_piecewise_sum(pw, j, S.Zero, n-1)
print("Helper result:", res)
print("Sum directly:", Sum(pw, (j, 0, n-1)).doit())
