from sympy import *
a = symbols('a')
def mat(n):
    return Matrix([[i + a*j for i in range(n)] for j in range(n)])
def dets(n):
    M = mat(n)
    return M.det(method='bareiss'), M.det(method='berkowitz')
for n in range(1,7):
    db, dk = dets(n)
    print("n=", n)
    for aval in [0,1,2,3,-1]:
        try:
            vb = db.subs(a, aval)
            vk = dk.subs(a, aval)
            print(" a=", aval, " bareiss=", vb, " berkowitz=", vk, " equal=", simplify(vb-vk)==0)
        except Exception as e:
            print(" a=", aval, " EXC:", e)
