from pathlib import Path
p = Path('sympy/combinatorics/homomorphisms.py')
s = p.read_text()

start = s.find("def _check_homomorphism(domain, codomain, images):")
if start == -1:
    raise SystemExit("Start of _check_homomorphism not found")

end = s.find("\ndef orbit_homomorphism(", start)
if end == -1:
    end = s.find("def orbit_homomorphism(", start)
if end == -1:
    raise SystemExit("End marker (orbit_homomorphism) not found")

new_func = '''
def _check_homomorphism(domain, codomain, images):
    if hasattr(domain, 'relators'):
        rels = domain.relators
    else:
        rels = domain.presentation().relators
    identity = codomain.identity

    def _pg_sym_to_dom(sym):
        # Map presentation symbols like x_1, x_2 to domain.generators[0], [1], ...
        name = str(sym)
        if name.startswith('x_'):
            try:
                idx = int(name.split('_', 1)[1]) - 1
                return domain.generators[idx]
            except Exception as e:
                raise KeyError(f"Cannot map presentation symbol {sym} to domain generator") from e
        # Fallback: try direct membership by equality (unlikely for permutation presentations)
        for g in domain.generators:
            if str(g) == name:
                return g
        raise KeyError(f"Unknown presentation symbol {sym}")

    def _image(r):
        if r.is_identity:
            return identity
        # For permutation groups, iterate over array_form (symbol, power)
        # and map each symbol to the corresponding domain generator.
        if isinstance(domain, PermutationGroup):
            w = identity
            for sym, power in r.array_form:
                s_dom = _pg_sym_to_dom(sym)
                w = w*images[s_dom]**power
            return w
        # Default for other groups: use original iteration over r and r.array_form
        w = identity
        r_arr = r.array_form
        i = 0
        j = 0
        while i < len(r):
            power = r_arr[j][1]
            s = r[i]
            if s in images:
                w = w*images[s]**power
            elif s**-1 in images:
                w = w*images[s**-1]**power
            i += abs(power)
            j += 1
        return w

    for r in rels:
        if isinstance(codomain, FpGroup):
            s = codomain.equals(_image(r), identity)
            if s is None:
                success = codomain.make_confluent()
                s = codomain.equals(_image(r), identity)
                if s is None and not success:
                    raise RuntimeError("Can't determine if the images define a homomorphism. "
                        "Try increasing the maximum number of rewriting rules "
                        "(group._rewriting_system.set_max(new_value); "
                        "the current value is stored in group._rewriting_system.maxeqns)")
        else:
            s = _image(r).is_identity
        if not s:
            return False
    return True

'''.lstrip('\n')

